1	import { getVersion } from "@tauri-apps/api/app";
2	import { writeText } from "@tauri-apps/plugin-clipboard-manager";
3	import { Show, createEffect, createSignal } from "solid-js";
4	import { useHotkeyRecorder } from "../hooks/useHotkeyRecorder";
5	import { useI18n } from "../i18n";
6	import { validateHandsFreeHotkey, validateHoldToSpeakHotkey } from "../lib/hotkeyUtils";
7	import {
8		type AudioDevice,
9		getAudioInputDevices,
10		updateHoldToSpeakHotkey,
11		useSettings,
12	} from "../lib/settingsStore";
13	import AppearanceSettings from "./settings/AppearanceSettings";
14	import AudioSettings from "./settings/AudioSettings";
15	import HotkeySettings from "./settings/HotkeySettings";
16	import LanguageSettings from "./settings/LanguageSettings";
17	import ModelSettings from "./settings/ModelSettings";
18	import SettingsSidebar from "./settings/SettingsSidebar";
19	import type { SettingsSection } from "./settings/types";
20	
21	interface SettingsModalProps {
22		isOpen: boolean;
23		onClose: () => void;
24	}
25	
26	const sectionTitles: Record<SettingsSection, string> = {
27		audio: "// AUDIO_CONFIG",
28		model: "// MODEL_CONFIG",
29		hotkey: "// HOTKEY_CONFIG",
30		appearance: "// APPEARANCE_CONFIG",
31		language: "// LANGUAGE_CONFIG",
32	};
33	
34	export default function SettingsModal(props: SettingsModalProps) {
35		const [t, { locale, setLocale }] = useI18n();
36		const settings = useSettings();
37		const [activeSection, setActiveSection] = createSignal<SettingsSection>("audio");
38		const [audioDevices, setAudioDevices] = createSignal<AudioDevice[]>([]);
39		const [appVersion, setAppVersion] = createSignal("");
40		const [versionCopied, setVersionCopied] = createSignal(false);
41	
42		const {
43			isRecording: isRecordingHotkey,
44			pendingHotkey,
45			error: hotkeyError,
46			toggleRecording: toggleHotkeyRecording,
47		} = useHotkeyRecorder({
48			validator: validateHandsFreeHotkey,
49			recorderId: "settings-handsfree",
50		});
51		const {
52			isRecording: isRecordingHoldToSpeakHotkey,
53			pendingHotkey: pendingHoldToSpeakHotkey,
54			error: holdToSpeakHotkeyError,
55			toggleRecording: toggleHoldToSpeakHotkeyRecording,
56		} = useHotkeyRecorder({
57			onHotkeyRecorded: updateHoldToSpeakHotkey,
58			validator: validateHoldToSpeakHotkey,
59			recorderId: "settings-holdtospeak",
60		});
61	
62		const handleCopyVersion = async () => {
63			if (versionCopied()) return;
64			await writeText(appVersion());
65			setVersionCopied(true);
66			setTimeout(() => setVersionCopied(false), 1500);
67		};
68	
69		const fetchAudioDevices = async () => {
70			const devices = await getAudioInputDevices();
71			setAudioDevices(devices);
72		};
73	
74		createEffect(() => {
75			if (props.isOpen) {
76				fetchAudioDevices();
77				getVersion().then(setAppVersion);
78			}
79		});
80	
81		createEffect(() => {
82			if (!props.isOpen) return;
83	
84			const handleEscape = (e: KeyboardEvent) => {
85				if (e.key === "Escape" && !isRecordingHotkey() && !isRecordingHoldToSpeakHotkey()) {
86					props.onClose();
87				}
88			};
89	
90			window.addEventListener("keydown", handleEscape);
91			return () => window.removeEventListener("keydown", handleEscape);
92		});
93	
94		const handleOverlayClick = (e: MouseEvent) => {
95			if (e.target === e.currentTarget) {
96				props.onClose();
97			}
98		};
99	
100		return (
101			<Show when={props.isOpen}>
102				{/* biome-ignore lint/a11y/useKeyWithClickEvents: the overlay click mirrors Escape handling. */}
103				<div
104					class="fixed inset-0 bg-th-overlay flex items-center justify-center z-50"
105					onClick={handleOverlayClick}
106				>
107					<div class="bg-th-base border border-border w-[800px] h-[600px] flex overflow-hidden">
108						<SettingsSidebar
109							activeSection={activeSection()}
110							appVersion={appVersion()}
111							versionCopied={versionCopied()}
112							onSectionChange={setActiveSection}
113							onCopyVersion={handleCopyVersion}
114						/>
115	
116						<div class="flex-1 flex flex-col">
117							<div class="flex items-center justify-between px-6 py-4 border-b border-border">
118								<h3 class="font-mono text-txt-primary text-sm tracking-wider uppercase">
119									{sectionTitles[activeSection()]}
120								</h3>
121								<button
122									type="button"
123									onClick={props.onClose}
124									class="font-mono text-txt-muted hover:text-ac transition-colors text-sm"
125								>
126									[X]
127								</button>
128							</div>
129	
130							<div class="flex-1 overflow-auto p-6">
131								<Show when={activeSection() === "audio"}>
132									<AudioSettings
133										t={t}
134										settings={settings}
135										audioDevices={audioDevices()}
136										onRefreshDevices={fetchAudioDevices}
137									/>
138								</Show>
139								<Show when={activeSection() === "model"}>
140									<ModelSettings t={t} />
141								</Show>
142								<Show when={activeSection() === "hotkey"}>
143									<HotkeySettings
144										t={t}
145										settings={settings}
146										isRecordingHotkey={isRecordingHotkey()}
147										pendingHotkey={pendingHotkey()}
148										hotkeyError={hotkeyError()}
149										onToggleHotkeyRecording={toggleHotkeyRecording}
150										isRecordingHoldToSpeakHotkey={isRecordingHoldToSpeakHotkey()}
151										pendingHoldToSpeakHotkey={pendingHoldToSpeakHotkey()}
152										holdToSpeakHotkeyError={holdToSpeakHotkeyError()}
153										onToggleHoldToSpeakHotkeyRecording={toggleHoldToSpeakHotkeyRecording}
154									/>
155								</Show>
156								<Show when={activeSection() === "appearance"}>
157									<AppearanceSettings settings={settings} />
158								</Show>
159								<Show when={activeSection() === "language"}>
160									<LanguageSettings locale={locale()} setLocale={setLocale} />
161								</Show>
162							</div>
